def esc(s):return s.replace('&','\\&').replace('%','\\%')
with (D/'root_records'/'references.bib').open('w') as f:
    for r in R:
        fields={'author':r['authors'],'title':r['title'],'year':r['year'],'url':r['url'],'note':'verified' if r['verified'] else 'unverified','annote':r['locator']+'; '+r['verification_scope']+' '+r['first_circulation']}
        if r['doi']:fields['doi']=r['doi']
        f.write('@'+r['type']+'{'+r['key']+',\n'+',\n'.join('  '+k+' = {'+esc(v)+'}' for k,v in fields.items())+'\n}\n\n')
with (D/'root_records'/'reference_events.tsv').open('w',newline='') as f:
    w=csv.writer(f,delimiter='\t');w.writerow(['statement_id','date','who','type','outcome'])
    for r in R:
        w.writerow([r['key'],'2026-11-19','GPT-6 Astra Pro; effort not exposed; SA07-part3/root',
          'used and rechecked in this run' if r['verified'] else 'carried as background without fault found',
          r['verification_scope']+' '+r['locator']+'; '+r['result_used']])
